using System;

/// <summary>Queues an order.</summary>
/// <param name="order">The order to queue.</param>
[Tag("add")]
public void Add(Order order)
{
	Order[] array = new Order[_orders.Length + 1];
	Array.Copy(_orders, array, _orders.Length);
	array[_orders.Length] = order;
	_orders = array;
	Processed?.Invoke(this, EventArgs.Empty);
}
